public class OwnerGrantProbe {
 public static String shares(Id parentId, Boolean governed, Id ownerId, Id groupId) {
  Integer total=0, owners=0, rules=0, manual=0; Boolean ownerMatch=true, ruleMatch=true;
  List<SObject> rows=Database.query('SELECT ParentId,UserOrGroupId,RowCause,AccessLevel FROM '+(governed?'OwnedRuleBox__Share':'OwnedPlainBox__Share')+' WHERE ParentId = :parentId');
  for(SObject row:rows) { total++; String cause=(String)row.get('RowCause');
   if(cause=='Owner'){owners++;ownerMatch=ownerMatch && row.get('UserOrGroupId')==ownerId && row.get('AccessLevel')=='All';}
   else if(cause=='Rule'){rules++;ruleMatch=ruleMatch && row.get('UserOrGroupId')==groupId && row.get('AccessLevel')=='Read';}
   else if(cause=='Manual'){manual++;}
  }
  return total+':'+owners+':'+rules+':'+manual+':'+ownerMatch+':'+ruleMatch;
 }
 public static String anonymousObservation() {
  Savepoint sp=Database.setSavepoint();
  try{
   OwnedRuleBox__c governed=new OwnedRuleBox__c(Name='Owned'); insert governed;
   OwnedPlainBox__c plain=new OwnedPlainBox__c(Name='Control'); insert plain;
   return 'governed:'+shares(governed.Id,true,UserInfo.getUserId(),null)+'|plain:'+shares(plain.Id,false,UserInfo.getUserId(),null);
  }finally{Database.rollback(sp);}
 }
}

