@IsTest private class OwnerGrantSpec {
 static User actor(String key) {
  return new User(Alias=key,Email=key+'@example.invalid',EmailEncodingKey='UTF-8',LastName=key,LanguageLocaleKey='en_US',LocaleSidKey='en_US',ProfileId=UserInfo.getProfileId(),TimeZoneSidKey='America/Los_Angeles',Username=key+'.'+String.valueOf(Datetime.now().getTime())+UserInfo.getOrganizationId()+'@example.invalid');
 }
 @IsTest static void baseline() {System.assert(false,'P|OG02T|'+OwnerGrantProbe.anonymousObservation());}
 @IsTest static void observe() {
  User inside=actor('origin'),outside=actor('outside');
  Group origin=[SELECT Id FROM Group WHERE DeveloperName='OwnedGrantOrigin'];
  Group target=[SELECT Id FROM Group WHERE DeveloperName='OwnedGrantTarget'];
  Integer before=[SELECT count() FROM GroupMember WHERE GroupId IN :new Set<Id>{origin.Id,target.Id}];
  insert new List<User>{inside,outside};
  insert new List<GroupMember>{new GroupMember(GroupId=origin.Id,UserOrGroupId=inside.Id),new GroupMember(GroupId=target.Id,UserOrGroupId=outside.Id)};
  String observation='members:'+before+':'+[SELECT count() FROM GroupMember WHERE GroupId IN :new Set<Id>{origin.Id,target.Id}];
  System.runAs(outside) {
   OwnedRuleBox__c governed=new OwnedRuleBox__c(Name='Owned');insert governed;
   OwnedPlainBox__c plain=new OwnedPlainBox__c(Name='Control');insert plain;
   observation+='|outside:'+OwnerGrantProbe.shares(governed.Id,true,outside.Id,target.Id);
   governed.OwnerId=inside.Id;update governed;
   observation+='|inside:'+OwnerGrantProbe.shares(governed.Id,true,inside.Id,target.Id);
   plain.OwnerId=inside.Id;update plain;
   observation+='|plain:'+OwnerGrantProbe.shares(plain.Id,false,inside.Id,target.Id);
   governed.OwnerId=outside.Id;update governed;
   observation+='|restored:'+OwnerGrantProbe.shares(governed.Id,true,outside.Id,target.Id);
  }
  System.assert(false,'P|OG01T|'+observation);
 }
}

