public class OwnerDeleteProbe {
 public static String observe() {
  Savepoint sp=Database.setSavepoint();
  try {
   OwnedPlainBox__c row=new OwnedPlainBox__c(Name='Owned lifecycle');insert row;
   Id parentId=row.Id;
   Integer initial=[SELECT count() FROM OwnedPlainBox__Share WHERE ParentId=:parentId];
   delete row;
   Integer removed=[SELECT count() FROM OwnedPlainBox__Share WHERE ParentId=:parentId];
   undelete row;
   List<OwnedPlainBox__Share> restored=[SELECT UserOrGroupId,AccessLevel,RowCause FROM OwnedPlainBox__Share WHERE ParentId=:parentId];
   Boolean restoredOwner=restored.size()==1 && restored[0].UserOrGroupId==UserInfo.getUserId() && restored[0].AccessLevel=='All' && restored[0].RowCause=='Owner';
   Boolean cascadeFlag=null;
   for(Schema.ChildRelationship relation:OwnedPlainBox__c.SObjectType.getDescribe().getChildRelationships()){
    if(relation.getChildSObject()==OwnedPlainBox__Share.SObjectType && relation.getField()==OwnedPlainBox__Share.ParentId){cascadeFlag=relation.isCascadeDelete();}
   }
   return 'shares:'+initial+':'+removed+':'+restored.size()+':'+restoredOwner+'|cascade:'+cascadeFlag;
  }finally{Database.rollback(sp);}
 }
}

